/* ENCORE 0.9.2 — business, collaboration, commerce, awards and sports depth pass. */
const V092_SCHEMA=1;
const V092_BUSINESS_SKILLS=['Acumen','Negotiation','A&R','Marketing','Management','Finance','Networking'];
let V092_sportsSport='All',V092_sportsPage=0;

function V092_num(v){const n=Number(v);return Number.isFinite(n)?n:0}
function V092_businessSeed(){return Object.fromEntries(V092_BUSINESS_SKILLS.map(k=>[k,{level:0,xp:0}]))}
function migrateV092(){
  if(!s.v092)s.v092={version:V092_SCHEMA,feature:{price:null,incoming:[],royalties:[],nextId:1},business:{skills:V092_businessSeed(),history:[]},sports:{},awards:{version:1}};
  const v=s.v092;v.version=V092_SCHEMA;
  v.feature??={price:null,incoming:[],royalties:[],nextId:1};v.feature.incoming??=[];v.feature.royalties??=[];v.feature.nextId??=1;
  v.business??={skills:V092_businessSeed(),history:[]};v.business.skills??=V092_businessSeed();v.business.history??=[];
  for(const key of V092_BUSINESS_SKILLS){const x=v.business.skills[key]||{level:0,xp:0};x.level=clamp(Math.round(V092_num(x.level)),0,100);x.xp=Math.max(0,V092_num(x.xp));v.business.skills[key]=x}
  v.sports??={};v.awards??={version:1};
  if(v.feature.price===null||v.feature.price===undefined)v.feature.price=V092_featureMarketValue();
  if(Array.isArray(V080_destinations)&&!V080_destinations.some(d=>d[2]==='BusinessHQ'))V080_destinations.splice(17,0,['Business HQ','Business','BusinessHQ','Run your companies, deals, merchandise, ownership and executive skills',4]);
  V092_expandSportsUniverse();V092_backfillAwards();
}
function V092_businessLevel(key){return s.v092?.business?.skills?.[key]?.level||0}
function V092_gainBusiness(key,xp){migrateV092();const skill=s.v092.business.skills[key];skill.xp+=Math.max(0,xp);const next=Math.min(100,Math.floor(Math.sqrt(skill.xp)*3.2));if(next>skill.level){skill.level=next;toast(key+' increased to '+next)}return skill.level}
function V092_logBusiness(text){migrateV092();s.v092.business.history.unshift({week:s.week,text:String(text).slice(0,180)});s.v092.business.history=s.v092.business.history.slice(0,80)}

/* Keep decimal values readable instead of truncating the readback. */
V090_readableNumber=function(value,moneyValue=false){const raw=String(value??'').replace(/,/g,'').trim();if(!raw)return '';const n=Number(raw);if(!Number.isFinite(n))return '';const decimals=raw.includes('.')?Math.min(2,(raw.split('.')[1]||'').length):0;const formatted=n.toLocaleString('en-US',{minimumFractionDigits:decimals,maximumFractionDigits:Math.max(decimals,2)}).replace(/\.00$/,'');let words='';if(Number.isSafeInteger(n)&&Math.abs(n)<=999999999999999)words=V090_numberWords(Math.abs(n));return `${moneyValue?'$':''}${formatted}${words?` · ${n<0?'negative ':''}${words}${moneyValue?' dollars':''}`:''}`};

/* One Studio creation interface: the 0.9 creative brief owns the whole writing setup. */
const V092_studio090=studio;
function V092_unifiedSongForm(){const idea=ensureStudioIdeaSchema(),opt=(items,current)=>items.map(x=>`<option ${x===current?'selected':''}>${esc(x)}</option>`).join('');return `<section class="card studio-active studio-v092"><div class="studio-tape-label"><span>SESSION 01</span><small>WRITE THE RECORD</small></div><h2>Start your next record</h2><form class="form studio-v092-form" onsubmit="newSong(event)"><label>Song title${nameInput('songtitle','song',idea.title||'','Name your next record')}</label><div class="creative-grid"><label>Theme<select onchange="setCreativeDirection('theme',this.value)">${opt(CREATIVE_THEMES,idea.theme||'Personal story')}</select></label><label>Tempo<select onchange="setCreativeDirection('tempo',this.value)">${opt(CREATIVE_TEMPOS,idea.tempo||'Mid-tempo')}</select></label><label>Intent<select onchange="setCreativeDirection('intent',this.value)">${opt(CREATIVE_INTENTS,idea.intent||'Balanced')}</select></label><label>Texture<select onchange="setCreativeDirection('texture',this.value)">${opt(CREATIVE_TEXTURES,idea.texture||'Warm & soulful')}</select></label><label>Hook approach<select onchange="setCreativeDirection('hook',this.value)">${opt(CREATIVE_HOOKS,idea.hook||'Melodic refrain')}</select></label><label>Mood<select name="mood" onchange="setCreativeDirection('mood',this.value)">${directions.map(x=>`<option value="${esc(x.id)}" ${x.id===(idea.mood||directions[0].id)?'selected':''}>${esc(x.name||x.id)}</option>`).join('')}</select></label><label>Writing approach<select name="brief" onchange="setCreativeDirection('brief',this.value)"><option value="story" ${(idea.brief||'story')==='story'?'selected':''}>Story-first</option><option value="anthem" ${idea.brief==='anthem'?'selected':''}>Anthem / hook-first</option><option value="experiment" ${idea.brief==='experiment'?'selected':''}>Experimental</option></select></label><label>Production budget<select name="package">${studioPackages.map((x,i)=>`<option value="${i}" ${String(i)===(idea.package||'0')?'selected':''}>${esc(x.name)} · ${x.fee?money(x.fee)+' upfront':'$0 upfront'}${x.quality?' · up to +'+x.quality+' quality':''}</option>`).join('')}</select></label></div><div class="studio-commit"><p>Writing starts a persistent project. Your creative choices affect identity, quality and commercial potential without guaranteeing a hit.</p><button class="primary">Start writing · 10 energy</button></div></form></section>`}
studio=function(){if(s.draft)return V092_studio090();const finished=s.songs.filter(x=>!x.album&&!x.released);return head('Shape the record before the world hears it','Studio.')+V092_unifiedSongForm()+`<section class="card studio-stack"><div class="sectionhead"><div><span class="eyebrow">FINISHED RECORDINGS</span><h2>Your release shelf</h2></div><button class="secondary" ${s.songs.filter(x=>!x.album).length<3?'disabled':''} onclick="albumForm()">Build album</button></div>${finished.map(x=>`<div class="project-row"><div><strong>${esc(x.title)}</strong><small>Quality ${x.quality}/100 · Commercial ${x.commercial??'—'}/100${guestList(x).length?' · '+guestList(x).length+' feature'+(guestList(x).length===1?'':'s'):''}</small></div><button class="secondary" onclick="releaseShelf(${x.id})">Release single</button></div>`).join('')||'<p class="fine">Finished unreleased tracks will wait here for a single or album.</p>'}</section>`};

/* Feature economy: artist-set asking price plus cash, royalty and hybrid structures. */
function V092_featureMarketValue(){const followers=s.social?.followers||0,streams=Math.max(s.streams||0,(s.empire?.lastMonth?.streams||0)),wins=s.expansion?.awardWins||0,power=Math.log10(1+s.fans)*1.4+Math.log10(1+followers)*.65+Math.log10(1+streams)*.7+s.reputation*.035+level('charisma')*.02+wins*.16;return Math.min(Number.MAX_SAFE_INTEGER,Math.max(100,Math.round(Math.pow(10,Math.max(2,power/2.8))/100)*100))}
function V092_featureBookingChance(price=s.v092?.feature?.price){const market=V092_featureMarketValue(),ask=Math.max(0,V092_num(price)),ratio=ask/Math.max(1,market),momentum=clamp((s.careerWorld?.momentum||0)/100,0,1);return clamp((1/(1+Math.max(0,ratio-1)*1.4))*(.62+momentum*.18+s.reputation/500),.01,.95)}
function V092_setFeaturePrice(e){e.preventDefault();migrateV092();const price=Number(new FormData(e.target).get('featurePrice'));if(!Number.isSafeInteger(price)||price<0){toast('Enter a whole-dollar feature price of $0 or more.');return}s.v092.feature.price=price;V092_gainBusiness('Negotiation',8);V092_logBusiness('Feature asking price set to '+money(price)+'.');queueSave();render();toast('Feature price updated · '+money(price))}
function V092_featureMarketCard(){migrateV092();const price=s.v092.feature.price,market=V092_featureMarketValue(),chance=V092_featureBookingChance(price);return `<section class="card feature-market"><span class="eyebrow">YOUR FEATURE MARKET</span><h2>Set your price. Let demand decide.</h2><p>You can charge any whole-dollar amount the save can safely store. Pricing above your current draw does not block you, but artists become less likely to approach until your audience catches up.</p>${profileRows([['Your asking price',money(price)],['Estimated market value',money(market)],['Current booking likelihood',Math.round(chance*100)+'%'],['Open royalty deals',String(s.v092.feature.royalties.filter(x=>x.active).length)]])}<form class="form feature-price-form" onsubmit="V092_setFeaturePrice(event)"><label>Standard feature price ($)<input type="number" name="featurePrice" min="0" max="9007199254740991" step="1" value="${price}" required></label><button class="primary">Update feature price</button></form><p class="fine">A high asking price can still work when your streams, reputation, awards, PULSE reach and momentum justify it. Incoming artists may also propose royalties or a hybrid instead of full cash.</p></section>`}
const V092_creativePage081=V081_creativePage;
V081_creativePage=function(){const html=V092_creativePage081();return html.replace('<div class="chips">',V092_featureMarketCard()+'<div class="chips">')};
const V092_addCreative081=V081_addCreativeOffer;
V081_addCreativeOffer=function(type,a){migrateV092();if(type!=='featureInvite')return V092_addCreative081(type,a);const price=s.v092.feature.price,artistBudget=Math.max(100,Math.round(baseFee(a)*(1.1+a.reputation/180))),afford=price?clamp(artistBudget/price,.08,1):1,chance=V092_featureBookingChance(price)*(.35+.65*afford);if(Math.random()>chance)return;const before=s.v081.creative.nextId;V092_addCreative081(type,a);const o=s.v081.creative.offers.find(x=>x.id===before);if(o){o.v092Feature=true;o.artistBudget=artistBudget;o.playerAsk=price;o.cashOffer=Math.min(price,artistBudget);o.royaltyOffer=clamp(.04+Math.max(0,price-artistBudget)/Math.max(1,price)*.08,.04,.15)}};
function V092_reviewIncomingFeature(id){migrateV092();const o=s.v081?.creative?.offers?.find(x=>x.id===id&&x.status==='open'),a=o&&s.world[o.artist];if(!o||!a)return;const ask=s.v092.feature.price,budget=o.artistBudget??Math.max(100,baseFee(a)),cash=Math.min(ask,budget),short=Math.max(0,ask-cash),royalty=clamp(o.royaltyOffer||.08,.02,.2),hybridCash=Math.min(budget,Math.round(ask*.35)),hybridRate=clamp(royalty*.6,.02,.12);modal(`${personPhoto('artist-'+(a.directoryKey??a.id),a.name,true)}<span class="eyebrow">FEATURE REQUEST</span><h2>${esc(a.name)} wants you on a record.</h2>${profileRows([['Your listed price',money(ask)],['Their available cash budget',money(budget)],['Cash shortfall',money(short)],['Your current market value',money(V092_featureMarketValue())]])}<div class="feature-deal-grid">${budget>=ask?`<button class="feature-deal" onclick="V092_acceptIncomingFeature(${id},'cash')"><strong>Full cash</strong><span>${money(ask)} upfront</span><small>No backend royalty.</small></button>`:''}<button class="feature-deal" onclick="V092_acceptIncomingFeature(${id},'hybrid')"><strong>Hybrid</strong><span>${money(hybridCash)} + ${(hybridRate*100).toFixed(1)}%</span><small>Smaller upfront payment plus royalties for 26 weeks.</small></button><button class="feature-deal" onclick="V092_acceptIncomingFeature(${id},'royalty')"><strong>Royalty split</strong><span>${(royalty*100).toFixed(1)}% royalties</span><small>No upfront fee. You earn when the record streams.</small></button></div><p class="fine">If your asking price outruns your current draw, fewer full-cash requests arrive. Royalty structures let both sides make the record without pretending the cash exists.</p><button class="secondary" onclick="V081_openDM(${a.id})">Message artist</button>`)}
const V092_acceptCreative081=V081_acceptCreative;
V081_acceptCreative=function(id){const o=s.v081?.creative?.offers?.find(x=>x.id===id&&x.status==='open');if(o?.type==='featureInvite')return V092_reviewIncomingFeature(id);return V092_acceptCreative081(id)};
function V092_acceptIncomingFeature(id,mode){migrateV092();const o=s.v081?.creative?.offers?.find(x=>x.id===id&&x.status==='open'),a=o&&s.world[o.artist];if(!o||!a||!['cash','hybrid','royalty'].includes(mode))return;const ask=s.v092.feature.price,budget=o.artistBudget??Math.max(100,baseFee(a)),royalty=clamp(o.royaltyOffer||.08,.02,.2),cash=mode==='cash'?Math.min(ask,budget):mode==='hybrid'?Math.min(budget,Math.round(ask*.35)):0,rate=mode==='cash'?0:mode==='hybrid'?clamp(royalty*.6,.02,.12):royalty;if(mode==='cash'&&budget<ask){toast('They cannot cover your full cash price. Try a hybrid or royalty split.');return}if(!spend(10))return;o.status='accepted';o.compensation={mode,cash,rate};if(cash){changeCash(cash);recordIncome('other',cash);moneyEvent('Feature fee · '+a.name,cash)}const title=generate('song'),baseStreams=Math.max(1000,Math.round((a.fans+s.fans*.15)*rand(.35,.75)));a.catalog.push({uid:a.nextCatalogId++,title:title+' (feat. '+s.name+')',type:'Single',week:s.week,base:baseStreams,streams:baseStreams,total:baseStreams,factor:1});if(rate>0)s.v092.feature.royalties.push({id:s.v092.feature.nextId++,artist:a.id,title,rate,baseStreams,weeks:26,remaining:26,active:true,totalPaid:0});a.relation=clamp(a.relation+5,-100,100);s.expansion.featureAppearances=(s.expansion.featureAppearances||0)+1;V092_gainBusiness('Networking',15);V092_gainBusiness('Negotiation',12);V092_logBusiness('Accepted '+mode+' feature deal with '+a.name+'.');$('modal').close();render();toast('Feature booked · '+(cash?money(cash)+' upfront':(rate*100).toFixed(1)+'% royalty'))}
function V092_settleIncomingFeatureRoyalties(){migrateV092();let total=0;for(const d of s.v092.feature.royalties.filter(x=>x.active)){const a=s.world[d.artist],momentum=a?Math.max(.35,1+(a.reputation-50)/250):.7,streams=Math.max(100,Math.round(d.baseStreams*momentum*rand(.82,1.08))),pay=cents(streams*.50*d.rate);if(pay>0){changeCash(pay);recordIncome('other',pay);d.totalPaid=cents((d.totalPaid||0)+pay);total+=pay}d.baseStreams=streams;d.remaining--;if(d.remaining<=0)d.active=false}if(total)moneyEvent('Feature royalty statements',total);return total}
const V092_beginCareer091=beginCareerWeek;
beginCareerWeek=function(){V092_beginCareer091();V092_settleIncomingFeatureRoyalties()};

function V092_outgoingFeatureTerms(a){const fee=quote(a),relation=Math.max(-40,a.relation||0),relative=Math.log10(1+s.fans)-Math.log10(1+a.fans),baseAccept=clamp(.5+relative*.16+relation/240+s.reputation/400,.08,.96);return {fee,cash:{upfront:fee,rate:0,chance:baseAccept},hybrid:{upfront:Math.round(fee*.30),rate:.075,chance:clamp(baseAccept+.08,.08,.98)},royalty:{upfront:0,rate:.15,chance:clamp(baseAccept+(relation>=50?.15:0)-(a.fans>s.fans*10?.15:0),.05,.95)}}}
studioGuest=function(id){const a=s.world[id],d=s.draft;if(!a||!d||guestList(d).some(g=>g.id===id)||guestList(d).length>=6)return;const terms=V092_outgoingFeatureTerms(a);modal(`${personPhoto('artist-'+(a.directoryKey??a.id),a.name,true)}<span class="eyebrow">FEATURE NEGOTIATION</span><h2>${esc(a.name)} · ${compact(a.fans)} fans</h2><p>Choose how to compensate the guest. Bigger artists can reject backend-only deals when your audience is not large enough to justify the risk.</p><div class="feature-deal-grid"><button class="feature-deal" onclick="V092_bookFeatureDeal(${id},'cash')"><strong>Cash fee</strong><span>${money(terms.cash.upfront)}</span><small>Est. acceptance ${Math.round(terms.cash.chance*100)}%</small></button><button class="feature-deal" onclick="V092_bookFeatureDeal(${id},'hybrid')"><strong>Hybrid</strong><span>${money(terms.hybrid.upfront)} + ${(terms.hybrid.rate*100).toFixed(1)}%</span><small>Est. acceptance ${Math.round(terms.hybrid.chance*100)}%</small></button><button class="feature-deal" onclick="V092_bookFeatureDeal(${id},'royalty')"><strong>Royalty split</strong><span>${(terms.royalty.rate*100).toFixed(0)}% of this song's artist royalties</span><small>Est. acceptance ${Math.round(terms.royalty.chance*100)}%</small></button></div>${featureRequirements(a)}<p class="fine">The royalty share applies only to this song and ends when you no longer receive simulated artist royalties from it.</p>`)};
function V092_bookFeatureDeal(id,mode){const a=s.world[id],d=s.draft,terms=a&&V092_outgoingFeatureTerms(a),t=terms?.[mode];if(!a||!d||!t||guestList(d).some(g=>g.id===id)||guestList(d).length>=6||!accessible(a))return;if(s.cash<t.upfront){toast('You do not have enough cash for that structure.');return}if(!spend(5))return;if(Math.random()>t.chance){toast(a.name+' passed on that split. Try a stronger offer or build more leverage.');return}if(t.upfront){changeCash(-t.upfront);s.finance.week.expenses=cents(V092_num(s.finance.week.expenses)+t.upfront);moneyEvent(a.name+' feature fee',-t.upfront)}d.features=[...guestList(d),{id,name:a.name,fans:a.fans,fee:t.upfront,dealType:mode,royaltyRate:t.rate}];d.feature=d.features[0];a.relation=clamp(a.relation+5,-100,100);a.discount=0;V092_gainBusiness('Negotiation',10);log(a.name+' joined '+d.title+' on a '+mode+' feature deal.');$('modal').close();render()}
function V092_featureRoyaltyExpense(){let due=0;for(const track of s.songs||[]){if(!track.released||!track.streams)continue;for(const g of guestList(track)){const rate=clamp(V092_num(g.royaltyRate),0,.5);if(rate>0)due+=track.streams*.50*rate}}return cents(due)}
const V092_closeFinances091=closeFinances;
closeFinances=function(royalties,rate){const featureRoyalty=V092_featureRoyaltyExpense();if(featureRoyalty>0){changeCash(-featureRoyalty);s.finance.week.expenses=cents(V092_num(s.finance.week.expenses)+featureRoyalty);moneyEvent('Guest feature royalties',-featureRoyalty)}const report=V092_closeFinances091(royalties,rate);report.featureRoyalty=featureRoyalty;return report};
const V092_financeRows091=financeRows;
financeRows=function(r,full=false){const adjusted=r.featureRoyalty?{...r,actionExpenses:Math.max(0,V092_num(r.actionExpenses)-V092_num(r.featureRoyalty))}:r;const rows=V092_financeRows091(adjusted,full);if(r.featureRoyalty){const i=Math.max(0,rows.findIndex(x=>String(x[0]).startsWith('Career/action expenses')));rows.splice(i,0,['Guest feature royalty splits','−'+money(r.featureRoyalty)])}return rows};

/* Contract negotiation: one responsive clause editor and a live interest model. */
function V092_contractClauseWeight(k){return ({masters:13,distribution:8,publishing:12,touring:9,merch:7,endorsements:5,media:4,syncMaster:4,syncPublishing:4})[k]||3}
function V092_contractInterest(o,t){const limits=labelBargainingLimits(o,t),max=Math.max(1,limits.maximum),r=V090_contractRights(t.type,t.rights),rightsScore=Object.keys(r).reduce((n,k)=>n+(r[k]?V092_contractClauseWeight(k):0),0),advancePressure=clamp(t.advance/max,0,2),shareComfort=clamp((t.share-limits.minimum)/.25,-1,1),term=(t.weeks-26)/104,career=s.reputation*.13+level('charisma')*.08+level('marketability')*.09+agentReach()*16+socialLeverage()*8+V092_businessLevel('Negotiation')*.08;return Math.round(clamp(52+career+rightsScore*.22+shareComfort*18+term*5-advancePressure*20,1,100))}
function V092_interestLabel(v){return v>=80?'Very strong interest':v>=65?'Strong interest':v>=50?'Negotiable':v>=35?'Fragile':'Walk-away risk'}
function V092_clauseText(checked,lockedOn,lockedOff){if(lockedOn)return 'Required by this deal structure';if(lockedOff)return 'Unavailable for this deal structure';return checked?'Included in company participation':'Artist retains / excluded'}
V090_rightsChecklist=function(type,rights={},editable=true){const spec=V090_CONTRACT_TYPES[type]||V090_CONTRACT_TYPES.record,r=V090_contractRights(type,rights);return `<fieldset class="contract-rights"><legend>Rights & participation</legend><p class="fine">Tap any available clause to include or exclude it. The label's interest meter updates with the entire package.</p>${Object.entries(V090_RIGHT_LABELS).map(([k,label])=>{const on=spec.lockedOn.includes(k),off=spec.lockedOff.includes(k),locked=on||off;return `<label class="contract-clause ${r[k]?'included':'excluded'}"><input type="checkbox" name="right_${k}" ${r[k]?'checked':''} ${(locked||!editable)?'disabled':''} onchange="V092_contractClauseChanged(this)"><span><strong><b class="clause-mark">${r[k]?'✓':'○'}</b> ${esc(label)}</strong><small>${esc(V092_clauseText(r[k],on,off))}</small></span></label>${locked&&r[k]?`<input type="hidden" name="right_${k}" value="on">`:''}`}).join('')}</fieldset>`};
function V092_contractClauseChanged(input){const label=input.closest?.('.contract-clause');if(label){label.classList.toggle('included',input.checked);label.classList.toggle('excluded',!input.checked);const mark=label.querySelector?.('.clause-mark'),small=label.querySelector?.('small');if(mark)mark.textContent=input.checked?'✓':'○';if(small)small.textContent=input.checked?'Included in company participation':'Artist retains / excluded'}const form=input.form;if(form)V092_refreshContractInterest(form,form.dataset.offerId)}
contractFields=function(t,artistOffer=false){return `${artistOffer?`<p>Proposed structure: <strong>${esc((V090_CONTRACT_TYPES[t.type]||{}).name||t.type)}</strong></p><input type="hidden" name="type" value="${esc(t.type)}">`:`<label>Contract type<select name="type">${[['record','Recording deal'],['distribution','Distribution deal'],['360','360 deal']].map(([v,n])=>`<option value="${v}" ${t.type===v?'selected':''}>${n}</option>`).join('')}</select></label>`}<label>Signing advance ($)<input type="number" name="advance" min="0" max="9007199254740991" step="1" value="${Math.round(t.advance)}" required></label><label>Company share (%)<input type="number" name="share" min="1" max="90" step="0.1" value="${+(t.share*100).toFixed(1)}" required></label><label>Contract length (weeks)<input type="number" name="weeks" min="4" max="104" step="1" value="${t.weeks}" required></label>${V090_rightsChecklist(t.type,t.rights,true)}`};
function V092_looseContractTerms(form){const f=new FormData(form),type=String(f.get('type')||'record'),share=clamp(V092_num(f.get('share'))/100,.01,.9),weeks=clamp(Math.round(V092_num(f.get('weeks'))||26),4,104),advance=Math.max(0,Math.round(V092_num(f.get('advance'))));return {type,share,weeks,advance,rights:V090_rightsInput(form,type)}}
function V092_refreshContractInterest(form,id){const o=s.labelBusiness?.offers?.find(x=>x.id===id);if(!o)return;const t=V092_looseContractTerms(form),score=V092_contractInterest(o,t),value=form.querySelector?.('#contract-interest-value'),bar=form.querySelector?.('#contract-interest-bar'),risk=form.querySelector?.('#contract-interest-risk');if(value)value.textContent=V092_interestLabel(score)+' · '+score+'/100';if(bar)bar.style.width=score+'%';if(risk)risk.textContent=score>=65?'The label is comfortable with this package.':score>=45?'This is within negotiating range, but pushing further increases rejection risk.':'High walk-away risk. Improve the economics, restore rights, or build more leverage.'}
reviewArtistOffer=function(id){const o=s.labelBusiness.offers.find(x=>x.id===id&&!x.used&&x.expires>=s.week);if(!labelActive()||!o||s.labelBusiness.company)return;const t=ensureLabelProposal(o),d=labelDeals[o.label],interest=V092_contractInterest(o,t);modal(`<span class="eyebrow">${esc(d.style||'Artist development')}</span><h2>${esc(d.name)}</h2><p>${esc(d.description||'Recording support for growing artists.')}</p><div class="contract-current">${profileRows([['Advance',money(t.advance)],['Company / artist split',+(t.share*100).toFixed(1)+'% / '+ +((1-t.share)*100).toFixed(1)+'%'],['Term',t.weeks+' weeks'],['Counter rounds',String(o.rounds||0)]])}</div>${o.response?`<p class="highlightbox">${esc(o.response)}</p>`:''}<form class="form contract-negotiator" data-offer-id="${id}" oninput="V092_refreshContractInterest(this,'${id}')" onchange="V092_refreshContractInterest(this,'${id}')" onsubmit="counterArtistOffer(event,'${id}')">${contractFields(t,true)}<section class="contract-interest"><div class="sectionhead"><strong>Label interest</strong><span id="contract-interest-value">${esc(V092_interestLabel(interest))} · ${interest}/100</span></div><div class="bar"><i id="contract-interest-bar" style="width:${interest}%"></i></div><p id="contract-interest-risk" class="fine">${interest>=65?'The label is comfortable with this package.':interest>=45?'Negotiable, but further asks increase rejection risk.':'High walk-away risk.'}</p></section><button class="primary">Send full-package counter · 5 energy</button></form><div class="controls"><button class="secondary" onclick="signNegotiatedOffer('${id}')">Review current proposal</button><button class="secondary" onclick="declineOffer('${id}')">Decline offer</button></div>`);V090_wireNumberReadbacks($('modal'))}
counterArtistOffer=function(e,id){e.preventDefault();const o=s.labelBusiness.offers.find(x=>x.id===id&&!x.used&&x.expires>=s.week);if(!labelActive()||!o||s.labelBusiness.company)return;try{const requested=contractInputTerms(e.target),current=ensureLabelProposal(o),d=labelDeals[o.label],allowed=d.types||['record','distribution','360'];if(requested.type!==current.type||!allowed.includes(requested.type)){toast('The label is holding to the proposed deal type. Negotiate the money, term and clauses.');return}if(!spend(5))return;const interest=V092_contractInterest(o,requested),limits=labelBargainingLimits(o,requested),accepted=interest>=58&&requested.share>=limits.minimum&&requested.advance<=limits.maximum;if(accepted)o.proposal=requested;else{o.proposal={...requested,advance:Math.min(requested.advance,Math.round((requested.advance+limits.maximum)/2)),share:Math.max(requested.share,limits.minimum),rights:interest<40?current.rights:requested.rights};o.proposal.rights=V090_contractRights(o.proposal.type,o.proposal.rights)}o.rounds=(o.rounds||0)+1;o.response=accepted?'They accepted the full package. Review the final rights and sign when ready.':'They countered. The package now reflects the money, term and rights they are willing to keep discussing.';V092_gainBusiness('Negotiation',accepted?24:14);V092_logBusiness((accepted?'Accepted':'Countered')+' label negotiation with '+d.name+'.');render();reviewArtistOffer(id)}catch(err){toast(err.message)}};
V090_youGiveGet=function(t){const r=V090_contractRights(t.type,t.rights),give=[],keep=[];for(const [k,label] of Object.entries(V090_RIGHT_LABELS))(r[k]?give:keep).push(label);return `<div class="contract-summary"><div><span class="eyebrow">COMPANY PARTICIPATES</span>${give.map(x=>`<p>✓ ${esc(x)}</p>`).join('')||'<p>No additional rights.</p>'}</div><div><span class="eyebrow">ARTIST RETAINS</span>${keep.map(x=>`<p>✓ ${esc(x)}</p>`).join('')||'<p>No excluded rights.</p>'}</div></div>`};

/* Merch 2.0: demand intelligence, inventory, preorder, on-demand/unlimited and giveaway campaigns. */
function V092_merchDemand(item,price){const m=merchItems.find(x=>x[0]===item),suggested=m?.[3]||30,active=Math.max(1,(s.empire?.merch||[]).filter(x=>x.mode!=='giveaway').length),priceFactor=Math.pow(suggested/Math.max(1,price),1.45),momentum=1+clamp((s.careerWorld?.momentum||0)/100,-.4,1)*.35,market=1+level('marketability')/180+V092_businessLevel('Marketing')/250,loyalty=.55+s.loyalty/140,base=s.fans*.012/Math.sqrt(active)*priceFactor*momentum*market*loyalty;return {low:Math.max(0,Math.round(base*.65)),mid:Math.max(0,Math.round(base)),high:Math.max(0,Math.round(base*1.35))}}
function V092_merchDemandMarkup(item,price){const d=V092_merchDemand(item,price);return profileRows([['Demand estimate',compact(d.low)+'–'+compact(d.high)+' units / month'],['Midpoint',compact(d.mid)+' units'],['Current true fans',compact(s.fans)],['Marketability',level('marketability')+'/100']])+'<p class="fine">Demand is an estimate, not a guarantee. Price, momentum, fan loyalty, product competition and marketability all matter.</p>'}
commercePage=function(){return head('Build products like a real artist business','Merchandise studio.')+`<section class="card merch-intro"><h2>Choose how you want to sell</h2><p>Hold inventory, open preorders before manufacturing, sell unlimited on-demand units, or run giveaways for reach. Every product shows a demand estimate before you commit.</p><button class="secondary" onclick="careerTab='Offers';render()">Open Offers Center</button></section><div class="wealth-grid">${merchItems.map(m=>`<button class="asset-tile" onclick="merchForm('${m[0]}')">${merchPhoto(m[0],0)}<h2>${esc(m[1])}</h2><p>${money(m[2])} production cost · Suggested ${money(m[3])}</p><strong>Build product →</strong></button>`).join('')}</div><section class="card"><h2>Active merchandise</h2>${s.empire.merch.map(m=>{const inventory=m.mode==='ondemand'?'Unlimited / on-demand':m.mode==='preorder'?compact(m.preorders||0)+' preorders':m.mode==='giveaway'?'Giveaway completed':compact(m.stock)+' in stock';return `<div class="merch-row"><div class="merch-inventory-art">${merchPhoto(m.item,m.look||0)}</div><div><strong>${esc(m.name)}</strong><small>${esc(m.mode||'inventory')} · ${inventory} · ${compact(m.sold||0)} sold${m.revenue?` · ${money(m.revenue)} gross`:''}</small>${m.mode==='preorder'&&m.preorders?`<button class="secondary" onclick="V092_fulfillPreorders(${m.id})">Fulfill ${compact(m.preorders)} preorders</button>`:''}</div><strong>${m.mode==='giveaway'?'FREE':money(m.price)}</strong></div>`}).join('')||'<p>No merchandise campaigns yet.</p>'}</section>`}
merchForm=function(id){const m=merchItems.find(x=>x[0]===id);if(!m)return;modal(`<h2>${esc(m[1])}</h2>${merchPhoto(id,0)}<form class="form merch-builder" data-item="${id}" oninput="V092_merchPreview(this,'${id}')" onsubmit="createMerch(event,'${id}')">${merchChoices(id)}<label>Sales model<select name="mode" onchange="V092_merchModeChanged(this.form)"><option value="inventory">Inventory · manufacture upfront</option><option value="preorder">Preorder · collect orders first</option><option value="ondemand">Unlimited / on-demand</option><option value="giveaway">Giveaway campaign</option></select></label><label class="merch-qty-field">Units<input name="qty" type="number" min="1" max="9007199254740991" step="1" value="100" required></label><label class="merch-price-field">Sale price ($)<input name="price" type="number" min="0" max="9007199254740991" step="0.01" value="${m[3]}" required></label><section id="merch-demand-preview" class="merch-demand">${V092_merchDemandMarkup(id,m[3])}</section><p>${money(m[2])} production cost per fulfilled unit. On-demand production is charged only when a unit sells. Preorders collect demand before you manufacture. Giveaways trade product cost for audience growth.</p><button class="primary">Review launch</button></form>`);V092_merchModeChanged($('modal').querySelector?.('form'));V090_wireNumberReadbacks($('modal'))}
function V092_merchModeChanged(form){if(!form)return;const mode=new FormData(form).get('mode'),qty=form.querySelector?.('.merch-qty-field'),price=form.querySelector?.('.merch-price-field');if(qty)qty.hidden=mode==='ondemand'||mode==='preorder';if(price)price.hidden=mode==='giveaway';const q=form.querySelector?.('input[name="qty"]'),p=form.querySelector?.('input[name="price"]');if(q)q.required=!(mode==='ondemand'||mode==='preorder');if(p)p.required=mode!=='giveaway';V092_merchPreview(form,form.dataset?.item)}
function V092_merchPreview(form,id){if(!form||!id)return;const f=new FormData(form),mode=String(f.get('mode')||'inventory'),price=mode==='giveaway'?0:Math.max(0,V092_num(f.get('price'))),el=form.querySelector?.('#merch-demand-preview');if(el)el.innerHTML=mode==='giveaway'?profileRows([['Campaign type','Free product giveaway'],['Estimated reach',compact(Math.round(Math.sqrt(Math.max(1,V092_num(f.get('qty'))))*Math.max(20,s.fans*.002)))]])+`<p class="fine">Giveaway reach depends on quantity, your audience and marketability.</p>`:V092_merchDemandMarkup(id,price)}
let V092_pendingMerch=null;
createMerch=function(e,id){e.preventDefault();const spec=merchItems.find(x=>x[0]===id),f=new FormData(e.target),mode=String(f.get('mode')||'inventory'),look=Number(f.get('look')||0),qty=['ondemand','preorder'].includes(mode)?0:Number(f.get('qty')),price=mode==='giveaway'?0:Number(f.get('price'));if(!spec||!['inventory','preorder','ondemand','giveaway'].includes(mode)||!Number.isInteger(look)||look<0||look>5)return;if(!['ondemand','preorder'].includes(mode)&&(!Number.isSafeInteger(qty)||qty<1))return;if(mode!=='giveaway'&&(!Number.isFinite(price)||price<0))return;const upfront=mode==='inventory'||mode==='giveaway'?cents(qty*spec[2]):0;V092_pendingMerch={item:id,look,name:spec[1]+' · '+merchandiseLooks[look],mode,stock:mode==='inventory'?qty:0,giveawayUnits:mode==='giveaway'?qty:0,preorders:0,sold:0,price,cost:upfront,unitCost:spec[2],revenue:0};modal(`${merchPhoto(id,look)}<h2>Launch ${esc(spec[1])}?</h2>${profileRows([['Sales model',mode==='ondemand'?'Unlimited / on-demand':mode==='preorder'?'Preorder':mode==='giveaway'?'Giveaway':'Inventory'],['Upfront production',money(upfront)],['Sale price',mode==='giveaway'?'Free':money(price)]])}${mode!=='giveaway'?V092_merchDemandMarkup(id,price):'<p>Free units will be distributed immediately and converted into simulated reach.</p>'}<button class="primary" onclick="confirmMerch()">Confirm launch · 10 energy</button>`)}
confirmMerch=function(){const m=V092_pendingMerch;if(!labelActive()||!m||!spend(10,m.cost))return;m.id=s.empire.nextId++;if(m.mode==='giveaway'){const reach=Math.round(Math.sqrt(m.giveawayUnits)*Math.max(20,s.fans*.002)*(1+level('marketability')/120));applyAudienceEvent('merch-giveaway',reach);if(s.social)s.social.followers+=Math.round(reach*1.8);m.stock=0;V092_gainBusiness('Marketing',18);V092_logBusiness('Ran '+compact(m.giveawayUnits)+'-unit giveaway campaign.')}else{s.empire.merch.push({...m});V092_gainBusiness('Marketing',12);V092_gainBusiness('Finance',6);V092_logBusiness('Launched '+m.name+' as '+m.mode+'.')}V092_pendingMerch=null;$('modal').close();render()}
function V092_fulfillPreorders(id){const m=s.empire.merch.find(x=>x.id===id&&x.mode==='preorder'),spec=m&&merchItems.find(x=>x[0]===m.item);if(!m||!spec||!m.preorders)return;const units=m.preorders,cost=cents(units*spec[2]),gross=cents(units*m.price);if(s.cash<cost){toast('You need '+money(cost)+' to manufacture these preorders.');return}changeCash(-cost);s.finance.week.expenses=cents(V092_num(s.finance.week.expenses)+cost);changeCash(gross);recordIncome('merch',gross);m.sold+=units;m.revenue=cents((m.revenue||0)+gross);m.preorders=0;moneyEvent(m.name+' preorder fulfillment',gross-cost);V092_gainBusiness('Finance',8);render();toast(compact(units)+' preorders fulfilled')}
settleCommerce=function(){const active=s.empire.merch.filter(m=>m.mode!=='giveaway');for(const m of active){const spec=merchItems.find(x=>x[0]===m.item);if(!spec)continue;const demand=V092_merchDemand(m.item,m.price),wanted=Math.max(0,Math.round(rand(demand.low,demand.high)));if(m.mode==='preorder'){m.preorders=Math.round((m.preorders||0)+wanted);continue}const sold=m.mode==='ondemand'?wanted:Math.min(m.stock,wanted),gross=cents(sold*m.price),cost=m.mode==='ondemand'?cents(sold*spec[2]):0;if(m.mode==='inventory')m.stock-=sold;if(cost){changeCash(-cost);s.finance.week.expenses=cents(V092_num(s.finance.week.expenses)+cost)}if(gross){changeCash(gross);recordIncome('merch',gross);m.sold+=sold;m.revenue=cents((m.revenue||0)+gross);moneyEvent(m.name+' sales',gross-cost)}}if(s.fans>=1000){const fee=Math.max(200,Math.round(s.fans*.015*(1+socialLeverage()))),o={id:s.empire.nextId++,name:pick(['Podcast appearance','Lifestyle brand campaign','Film sync licence','Festival media interview','Fashion editorial partnership']),fee,max:Math.round(fee*(1.2+s.reputation/200+socialLeverage()*.3)),rounds:0,expires:s.week+9,used:false};s.empire.media.push(o);addBriefing('media:'+o.id,'Opportunity','A media offer arrived',o.name+' offered '+money(fee)+'. Review, counter or decline in Commerce & media.')}s.empire.media=s.empire.media.filter(o=>o.expires>=s.week).slice(-20)};

/* ENCORE Honors metadata: winning work, simulated panel votes and repeat-category wins. */
function V092_yearRange(year){return {lo:(year-1)*52,hi:year*52}}
function V092_playerAwardWork(category,year){const {lo,hi}=V092_yearRange(year),songs=s.songs.filter(x=>x.released>lo&&x.released<=hi),albums=s.albums.filter(x=>x.week>lo&&x.week<=hi);if(category==='Album of the Year'){const a=albums.sort((a,b)=>albumStreams(b,true)-albumStreams(a,true))[0];return a?.title||null}if(category==='Live Act of the Year'){const t=(s.careerRecords?.tours||[]).filter(x=>x.week>lo&&x.week<=hi).sort((a,b)=>(b.gross||0)-(a.gross||0))[0];return t?.title||'Artist performance'}if(['Artist of the Year','Best New Artist','Fan Choice'].includes(category))return s.name;const pool=category==='Best Collaboration'?songs.filter(x=>guestList(x).length):songs;return pool.sort((a,b)=>awardScore(b)-awardScore(a))[0]?.title||null}
function V092_npcAwardWork(name,category,year){const a=s.world.find(x=>x.name===name);if(!a)return name;if(['Artist of the Year','Best New Artist','Fan Choice','Live Act of the Year'].includes(category))return a.name;const {lo,hi}=V092_yearRange(year),pool=(a.catalog||[]).filter(x=>(x.week||0)>lo&&(x.week||0)<=hi&&(category!=='Album of the Year'||x.type==='Album'));return pool.sort((x,y)=>(y.total||0)-(x.total||0))[0]?.title||'Archived release'}
function V092_votesForNominees(nominees){const weights=nominees.map(n=>Math.max(1,Math.pow(Math.max(1,n.score||1),2.2))),sum=weights.reduce((a,b)=>a+b,0)||1;let used=0;return nominees.map((n,i)=>{const votes=i===nominees.length-1?Math.max(0,1000-used):Math.max(1,Math.floor(weights[i]/sum*1000));used+=votes;return votes})}
function V092_ordinal(n){const m=n%100;return n+(m>=11&&m<=13?'th':n%10===1?'st':n%10===2?'nd':n%10===3?'rd':'th')}
function V092_backfillAwards(){const ceremonies=s.v080?.awards?.ceremonies||[];for(const c of ceremonies){for(const r of c.results||[]){const votes=V092_votesForNominees(r.nominees||[]);for(let i=0;i<(r.nominees||[]).length;i++){const n=r.nominees[i];n.votes??=votes[i];n.work??=(n.you?V092_playerAwardWork(r.category,c.year):V092_npcAwardWork(n.name,r.category,c.year))}const winner=(r.nominees||[]).find(n=>n.name===r.winner);r.winningWork??=winner?.work||null;r.winnerVotes??=winner?.votes||0}}for(const c of ceremonies){for(const r of c.results||[]){if(r.won)r.categoryCareerWin=ceremonies.filter(x=>x.year<=c.year).reduce((n,x)=>n+((x.results||[]).some(y=>y.category===r.category&&y.won)?1:0),0)}}}
const V092_annualAwards080=annualAwards;
annualAwards=function(){V092_annualAwards080();V092_backfillAwards();queueSave()};
function V092_categoryWinCount(category){return (s.v080?.awards?.ceremonies||[]).reduce((n,c)=>n+((c.results||[]).some(r=>r.category===category&&r.won)?1:0),0)}
V080_awardsPage=function(){migrateV092();const ceremonies=s.v080.awards.ceremonies.slice().reverse(),latest=ceremonies[0];return head('The biggest night in your career','The ENCORE Honors.',`<span class="pill">${s.expansion.awardWins||0} wins</span>`)+`<section class="awards-hero"><div><span class="eyebrow">ANNUAL AWARDS SHOW</span><h1>THE ENCORE<br>HONORS</h1><p>Every category now records the winning work, panel vote and your career win count in that category.</p></div><div class="award-stat"><strong>${s.expansion.awardWins||0}</strong><span>Career wins</span><strong>${s.expansion.awardNominations||0}</strong><span>Nominations</span></div></section>${latest?`<section class="card honors-ceremony"><div class="sectionhead"><h2>Year ${latest.year} ceremony</h2><span>${latest.wins} wins · ${latest.nominations} nominations</span></div><div class="award-category-grid">${latest.results.map(r=>`<article class="award-category ${r.won?'winner':''}"><span class="eyebrow">${esc(r.category)}</span><h3>${esc(r.winner||'No winner')}</h3><p class="award-work">${esc(r.winningWork||'Winning work not recorded')}</p><div class="award-result-line"><strong>${r.won?'🏆 YOU WON':r.nominated?'NOMINATED':'Not nominated'}</strong><span>${r.winnerVotes||0} / 1,000 panel votes</span></div>${r.won?`<p class="fine">Your ${V092_ordinal(r.categoryCareerWin||V092_categoryWinCount(r.category))} career ${esc(r.category)} win.</p>`:''}<details><summary>Nominees & votes</summary>${r.nominees.map(n=>`<div class="row"><span>${n.you?'<strong>'+esc(n.name)+'</strong>':esc(n.name)}<small>${esc(n.work||'')}</small></span><strong>${n.votes||0} votes</strong></div>`).join('')}</details></article>`).join('')}</div></section>`:`<section class="card"><h2>Your first ceremony arrives at the end of Year 1.</h2><p>Release music, chart, tour and grow your audience to enter the conversation.</p></section>`}<section class="card"><h2>Awards history</h2>${ceremonies.map(c=>`<details class="honors-history"><summary>Year ${c.year} · ${c.wins} wins / ${c.nominations} nominations</summary>${(c.results||[]).filter(r=>r.won||r.nominated).map(r=>`<div class="row"><span>${esc(r.category)}${r.winningWork?' · '+esc(r.winningWork):''}</span><strong>${r.won?'WIN #'+(r.categoryCareerWin||V092_categoryWinCount(r.category)):'Nominee'}</strong></div>`).join('')}</details>`).join('')||'<p>No completed ceremonies yet.</p>'}</section>`};

/* Sports ownership 2.0: broad universe, no arbitrary 10% cap, full ownership and owner decisions. */
const V092_TEAM_MARKETS=['Nashville','Phoenix','Denver','Boston','Las Vegas','San Diego','Portland','Charlotte','Detroit','Philadelphia','Houston','San Antonio','Orlando','Cleveland','Baltimore','New Orleans','Kansas City','Salt Lake','Sacramento','Tampa Bay','Minneapolis','Washington','St. Louis','Raleigh'];
const V092_TEAM_NAMES=['Rhythm','Scorpions','Altitude','Harbor','Aces','Breakers','Pines','Crown','Motors','Liberty','Orbit','Spurside','Magic City','Forge','Harborhawks','Brass','Kingsmen','Summit','Gold','Storm','Northstar','Monument','Archers','Oaks'];
function V092_expandSportsUniverse(){if(!s.v081?.sports?.teams)return;const teams=s.v081.sports.teams,existing=new Set(teams.map(t=>t.name));for(let i=0;i<V092_TEAM_MARKETS.length;i++){const name=V092_TEAM_MARKETS[i]+' '+V092_TEAM_NAMES[i];if(existing.has(name))continue;const id=Math.max(-1,...teams.map(t=>t.id))+1,sport=['Basketball','Football','Baseball','Soccer'][i%4],value=[1800000000,4200000000,3200000000,1100000000][i%4]*(.75+(i%7)*.08);teams.push({id,name,sport,value:Math.round(value),rating:48+(i*9)%44,wins:0,losses:0,season:1,games:0,history:[],championships:0,playoffAppearances:0,seasonsCompleted:0,management:{strategy:'balanced',ticket:'balanced',facilities:0,capital:0}})}for(const t of teams){t.championships??=0;t.playoffAppearances??=0;t.seasonsCompleted??=0;t.management??={strategy:'balanced',ticket:'balanced',facilities:0,capital:0}}}
function V092_teamShare(t){return clamp(V081_sportsHolding(t),0,1)}
function V092_shareLabel(share){return share>=.999?'Full owner':share>=.51?'Controlling owner':share>0?'Investor':'No stake'}
function V092_reviewSportsBuy(e,id){e.preventDefault();const pct=Number(new FormData(e.target).get('pct'));if(!Number.isFinite(pct)||pct<=0){toast('Enter an ownership percentage above 0.');return}V092_buySports(id,pct/100)}
function V092_buySports(id,share,confirmed=false){migrateV092();const t=s.v081.sports.teams.find(x=>x.id===id),owned=t?V092_teamShare(t):0,remaining=Math.max(0,1-owned);share=Math.min(remaining,V092_num(share));if(!t||share<=0)return;const price=cents(t.value*share*1.01);if(!confirmed){modal(`<h2>Buy ${(share*100).toFixed(2)}% of ${esc(t.name)}?</h2>${profileRows([['Current ownership',(owned*100).toFixed(2)+'%'],['Ownership after purchase',((owned+share)*100).toFixed(2)+'%'],['Stake price + 1% spread',money(price)],['Control after purchase',V092_shareLabel(owned+share)]])}<p>There is no arbitrary 10% game cap anymore. The only ownership ceiling is 100% of the franchise.</p><button class="primary" onclick="V092_buySports(${id},${share},true)">Confirm purchase</button>`);return}if(s.cash<price){toast('Not enough cash for that stake.');return}changeCash(-price);let remainingShare=share;while(remainingShare>0.0000001){const chunk=Math.min(.1,remainingShare),basis=cents(t.value*chunk*1.01);s.v081.sports.holdings.push({id:s.v081.sports.nextId++,team:id,share:chunk,basis,boughtMonth:s.empire.month,payouts:0,history:[{month:s.empire.month,value:t.value*chunk}]});remainingShare-=chunk}moneyEvent('Sports ownership · '+t.name,-price);V092_gainBusiness('Finance',18);V092_gainBusiness('Acumen',12);V092_logBusiness('Bought '+(share*100).toFixed(2)+'% of '+t.name+'.');$('modal').close();render()}
V081_buySports=V092_buySports;
function V092_sellSportsTeam(id,confirmed=false){const t=s.v081.sports.teams.find(x=>x.id===id),holds=s.v081.sports.holdings.filter(x=>x.team===id);if(!t||!holds.length)return;const share=holds.reduce((n,h)=>n+h.share,0),gross=cents(t.value*share),proceeds=cents(gross*.99),basis=holds.reduce((n,h)=>n+h.basis,0),gain=cents(proceeds-basis);if(!confirmed){modal(`<h2>Sell your ${(share*100).toFixed(2)}% stake in ${esc(t.name)}?</h2>${profileRows([['Current stake value',money(gross)],['Sale proceeds after 1% spread',money(proceeds)],['Cost basis',money(basis)],['Realized gain / loss',money(gain)]])}<button class="primary" onclick="V092_sellSportsTeam(${id},true)">Sell entire stake</button>`);return}changeCash(proceeds);s.finance.week.investment=cents(V092_num(s.finance.week.investment)+gain);s.v081.sports.holdings=s.v081.sports.holdings.filter(x=>x.team!==id);V092_logBusiness('Sold sports stake in '+t.name+'.');$('modal').close();render()}
function V092_manageTeam(id){const t=s.v081.sports.teams.find(x=>x.id===id),share=t&&V092_teamShare(t);if(!t||share<.51)return;const m=t.management||{};modal(`<span class="eyebrow">${share>=.999?'FULL OWNERSHIP':'CONTROLLING OWNERSHIP'}</span><h2>${esc(t.name)} front office</h2>${profileRows([['Ownership',(share*100).toFixed(2)+'%'],['Team rating',t.rating+'/100'],['Franchise value',money(t.value)],['Championships',String(t.championships||0)]])}<form class="form" onsubmit="V092_saveTeamPlan(event,${id})"><label>Competitive strategy<select name="strategy"><option value="rebuild" ${m.strategy==='rebuild'?'selected':''}>Rebuild · develop long term</option><option value="balanced" ${m.strategy==='balanced'?'selected':''}>Balanced</option><option value="contend" ${m.strategy==='contend'?'selected':''}>Win now · higher cost / volatility</option></select></label><label>Ticket strategy<select name="ticket"><option value="value" ${m.ticket==='value'?'selected':''}>Value pricing · fan growth</option><option value="balanced" ${m.ticket==='balanced'?'selected':''}>Balanced</option><option value="premium" ${m.ticket==='premium'?'selected':''}>Premium pricing · higher distributions</option></select></label><label>Capital / facilities investment ($)<input name="capital" type="number" min="0" max="9007199254740991" step="1" value="0"></label><p class="fine">Capital permanently improves facilities and can lift rating and franchise value. Strategy influences future seasons; it does not guarantee wins.</p><button class="primary">Apply owner decisions</button></form>`);V090_wireNumberReadbacks($('modal'))}
function V092_saveTeamPlan(e,id){e.preventDefault();const t=s.v081.sports.teams.find(x=>x.id===id),share=t&&V092_teamShare(t),f=new FormData(e.target),strategy=String(f.get('strategy')),ticket=String(f.get('ticket')),capital=Math.max(0,Math.round(V092_num(f.get('capital'))));if(!t||share<.51||!['rebuild','balanced','contend'].includes(strategy)||!['value','balanced','premium'].includes(ticket))return;if(s.cash<capital){toast('Not enough cash for that capital investment.');return}if(capital){changeCash(-capital);s.finance.week.expenses=cents(V092_num(s.finance.week.expenses)+capital);t.management.facilities=V092_num(t.management.facilities)+capital;t.management.capital=V092_num(t.management.capital)+capital;t.value=cents(t.value+capital*.65);t.rating=clamp(Math.round(t.rating+Math.log10(1+capital/1000000)*1.4),30,99);moneyEvent(t.name+' owner capital',-capital)}t.management.strategy=strategy;t.management.ticket=ticket;V092_gainBusiness('Management',20);V092_gainBusiness('Acumen',12);V092_logBusiness('Set '+t.name+' strategy to '+strategy+' / '+ticket+'.');$('modal').close();render()}
V081_settleSports=function(){migrateV092();if(s.v081.sports.lastSettledMonth===s.empire.month)return 0;s.v081.sports.lastSettledMonth=s.empire.month;let payouts=0;for(const t of s.v081.sports.teams){const m=t.management||{},gamesThisMonth=t.sport==='Baseball'?22:t.sport==='Basketball'?10:t.sport==='Football'?4:6,strategy=m.strategy||'balanced',winAdj=strategy==='contend'?.045:strategy==='rebuild'?-.025:0,facilityAdj=Math.min(.05,Math.log10(1+V092_num(m.facilities)/1000000)*.008);for(let i=0;i<gamesThisMonth;i++){const win=Math.random()<clamp(.25+t.rating/200+winAdj+facilityAdj,.22,.86);if(win)t.wins++;else t.losses++;t.games++}const seasonGames={Baseball:162,Basketball:82,Football:17,Soccer:34}[t.sport],pct=t.games?t.wins/t.games:.5,performance=(pct-.5)*.085,strategyValue=strategy==='contend'?.006:strategy==='rebuild'?.002:.004,move=strategyValue+performance+facilityAdj*.16+rand(-.025,.025);t.value=cents(Math.max(100000000,t.value*(1+move)));t.history.push({month:s.empire.month,value:t.value});t.history=t.history.slice(-36);if(t.games>=seasonGames){t.seasonsCompleted=(t.seasonsCompleted||0)+1;if(pct>=.55)t.playoffAppearances=(t.playoffAppearances||0)+1;if(pct>=.68&&Math.random()<clamp(.18+(pct-.68)*1.8,0,.72))t.championships=(t.championships||0)+1;t.season++;t.rating=clamp(Math.round(t.rating+(pct-.5)*12+(strategy==='rebuild'?2:strategy==='contend'?-1:0)+rand(-4,4)),35,98);t.wins=0;t.losses=0;t.games=0}}for(const h of s.v081.sports.holdings){const t=s.v081.sports.teams.find(x=>x.id===h.team);if(!t)continue;const ticket=t.management?.ticket||'balanced',yieldMult=ticket==='premium'?1.18:ticket==='value'?.86:1,distribution=cents(t.value*h.share*.00035*yieldMult);if(distribution>0){changeCash(distribution);recordIncome('investment',distribution);h.payouts=cents((h.payouts||0)+distribution);payouts+=distribution}h.history.push({month:s.empire.month,value:t.value*h.share});h.history=h.history.slice(-36)}return payouts};
V081_sportsPage=function(){migrateV092();const teams=s.v081.sports.teams,filtered=teams.filter(t=>V092_sportsSport==='All'||t.sport===V092_sportsSport),pages=Math.max(1,Math.ceil(filtered.length/8));V092_sportsPage=Math.min(V092_sportsPage,pages-1);const totalValue=s.v081.sports.holdings.reduce((n,h)=>{const t=teams.find(x=>x.id===h.team);return n+(t?t.value*h.share:0)},0);return head('Invest, control, or own the whole franchise','Sports ownership.',`<span class="pill">${money(totalValue)} owned</span>`)+`<section class="card"><p>No arbitrary team-count or 10% stake cap. You can invest across every franchise and build up to 100% ownership of any team. Majority control unlocks front-office decisions.</p><div class="chips">${['All','Basketball','Football','Baseball','Soccer'].map(x=>`<button class="${V092_sportsSport===x?'selected':''}" onclick="V092_sportsSport='${x}';V092_sportsPage=0;render()">${x}</button>`).join('')}</div></section><div class="catalog-market-grid">${filtered.slice(V092_sportsPage*8,V092_sportsPage*8+8).map(t=>{const f=V081_sportsForecast(t),owned=V092_teamShare(t),seasonGames={Baseball:162,Basketball:82,Football:17,Soccer:34}[t.sport];return `<section class="card sports-franchise"><span class="eyebrow">${esc(t.sport)} · SEASON ${t.season}</span><h2>${esc(t.name)}</h2>${profileRows([['Franchise value',money(t.value)],['Current record',t.wins+'–'+t.losses+' · '+t.games+'/'+seasonGames+' games'],['Team rating',t.rating+'/100'],['Championships',String(t.championships||0)],['Your ownership',(owned*100).toFixed(2)+'% · '+V092_shareLabel(owned)],['Annual value range',V081_pct(f.low)+' to '+V081_pct(f.high)]])}${V081_spark(t.history.map(x=>x.value),t.name+' franchise value trend')}<div class="controls">${[.01,.10,.25].filter(sh=>owned+sh<=1.000001).map(sh=>`<button class="secondary" onclick="V092_buySports(${t.id},${sh})">Buy ${Math.round(sh*100)}%</button>`).join('')}${owned<.999?`<button class="secondary" onclick="V092_buySports(${t.id},${1-owned})">Buy remaining</button>`:''}</div><form class="inline-buy" onsubmit="V092_reviewSportsBuy(event,${t.id})"><label>Custom %<input type="number" name="pct" min="0.01" max="${Math.max(.01,(1-owned)*100)}" step="0.01" value="1"></label><button class="secondary">Review</button></form>${owned>=.51?`<button class="primary" onclick="V092_manageTeam(${t.id})">Owner decisions</button>`:''}${owned>0?`<button class="secondary" onclick="V092_sellSportsTeam(${t.id})">Review sale</button>`:''}</section>`}).join('')}</div><div class="controls"><button class="secondary" ${V092_sportsPage===0?'disabled':''} onclick="V092_sportsPage--;render()">Previous</button><span>${V092_sportsPage+1}/${pages}</span><button class="secondary" ${V092_sportsPage>=pages-1?'disabled':''} onclick="V092_sportsPage++;render()">Next</button></div>`};

/* Business HQ + executive skills tie the separate money systems into one place. */
function V092_businessValue(){const sports=s.v081?.sports?.holdings?.reduce((n,h)=>{const t=s.v081.sports.teams.find(x=>x.id===h.team);return n+(t?t.value*h.share:0)},0)||0,catalog=s.v080?.catalog?.holdings?.reduce((n,h)=>n+(h.lastValue||0),0)||0,assets=s.empire?.assets?.reduce((n,a)=>n+(a.value||0),0)||0,inventory=s.empire?.merch?.reduce((n,m)=>n+(m.mode==='inventory'?(m.stock||0)*(m.unitCost||0):0),0)||0;return cents(sports+catalog+assets+inventory)}
function V092_trainBusiness(key){if(!V092_BUSINESS_SKILLS.includes(key))return;const levelNow=V092_businessLevel(key),cost=Math.round(500*Math.pow(1.18,levelNow));if(!spend(10,cost))return;V092_gainBusiness(key,25+levelNow*.6);V092_logBusiness('Completed '+key+' executive training.');render()}
function V092_businessPage(){migrateV092();const co=s.labelBusiness?.company,contracts=s.v080?.commercial?.contracts?.filter(x=>x.active).length||0,sportsTeams=new Set((s.v081?.sports?.holdings||[]).map(h=>h.team)).size;return head('From artist to owner','Business HQ.',`<span class="pill">${money(V092_businessValue())} business assets</span>`)+`<section class="business-command"><span class="eyebrow">EXECUTIVE OVERVIEW</span><h2>${co?esc(co.name):esc(s.name)+' Enterprises'}</h2>${metricRail([['Business assets',money(V092_businessValue())],['Active commercial deals',String(contracts)],['Sports franchises',String(sportsTeams)],['Merch campaigns',String(s.empire?.merch?.length||0)]])}<div class="business-jumps"><button onclick="careerTab='Offers';render()">Offers center</button><button onclick="careerTab='Deals';render()">Contracts & rights</button><button onclick="careerTab='Labels';render()">Label</button><button onclick="careerTab='Commerce';render()">Merchandise</button><button onclick="careerTab='Creative';render()">Creative network</button><button onclick="careerTab='Sports';render()">Sports ownership</button><button onclick="careerTab='CatalogMarket';render()">Catalog market</button><button onclick="careerTab='Team';render()">Executive team</button></div></section><section class="card"><span class="eyebrow">BUSINESS SKILLS</span><h2>Build the operator, not just the artist.</h2><p>Business skills improve as you negotiate, invest and manage. You can also train them directly; higher levels will feed deeper business systems over time.</p><div class="business-skill-grid">${V092_BUSINESS_SKILLS.map(k=>{const x=s.v092.business.skills[k];return `<div><span>${esc(k)}</span><strong>${x.level}/100</strong><div class="bar"><i style="width:${x.level}%"></i></div><button class="secondary" onclick="V092_trainBusiness('${k}')">Train · 10 energy</button></div>`}).join('')}</div></section><section class="card"><h2>Recent business decisions</h2>${s.v092.business.history.slice(0,12).map(x=>`<div class="story"><small>WEEK ${x.week}</small>${esc(x.text)}</div>`).join('')||'<p>Your negotiations, ownership moves and product launches will build this record.</p>'}</section>`}

