const V092_validate091=validatePresentationState;
validatePresentationState=function(){V092_validate091();if(!s.v092)return;const v=s.v092;if(v.version!==V092_SCHEMA||!v.feature||!v.business||!Array.isArray(v.feature.royalties)||!Array.isArray(v.business.history))throw Error('Invalid 0.9.2 state');if(!Number.isSafeInteger(v.feature.price)||v.feature.price<0)throw Error('Invalid feature price');for(const d of v.feature.royalties)if(!Number.isInteger(d.id)||!Number.isFinite(d.rate)||d.rate<0||d.rate>.5||!Number.isInteger(d.remaining)||d.remaining<0||typeof d.active!=='boolean')throw Error('Invalid feature royalty deal');for(const k of V092_BUSINESS_SKILLS){const x=v.business.skills[k];if(!x||!Number.isFinite(x.level)||x.level<0||x.level>100||!Number.isFinite(x.xp)||x.xp<0)throw Error('Invalid business skill')}};
